SELECT O.ORDER_ID AS orderId, O.MEMBER_ID AS memberId, O.ORDER_DT AS orderDt, O.ORDER_STATUS AS statusCode, O.TOTAL_AMT AS totalAmt FROM TB_ORDER O
AND O.MEMBER_ID = #{memberId}
AND O.ORDER_STATUS IN #{s}
AND O.ORDER_DT >= #{fromDt}
ORDER BY
O.TOTAL_AMT DESC O.ORDER_DT DESC, O.ORDER_ID DESC O.ORDER_ID DESC

SELECT ORDER_ID, MEMBER_ID, ORDER_DT, TOTAL_AMT
  FROM ${tableName}
 WHERE ORDER_DT < #{baseDt}
 ORDER BY ${orderBy}

